//! Docker policy. Configuration may add protected paths, never remove the baseline.
use anyhow::{ensure, Result};
use serde::{Deserialize, Serialize};
use std::path::{Path, PathBuf};

#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(default, deny_unknown_fields, rename_all = "camelCase")]
pub struct Config {
    pub mounts: Vec<Mount>,
    pub protected_paths: Vec<PathBuf>,
    pub memory_bytes: u64,
    pub cpus: f64,
    pub cap_add: Vec<String>,
    pub workdir_change: WorkdirChange,
}
#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct Mount {
    /// ${project}, ${kb}, or an absolute path matching the requested root.
    pub source: String,
    pub destination: String,
    pub read_only: bool,
}
#[derive(Clone, Copy, Debug, Deserialize, Serialize, PartialEq)]
#[serde(rename_all = "kebab-case")]
pub enum WorkdirChange { Reject, Rebuild }
impl Default for Config {
    fn default() -> Self {
        Self {
            mounts: vec![
                Mount { source: "${project}".into(), destination: "/workspace".into(), read_only: false },
                Mount { source: "${kb}".into(), destination: "/kb".into(), read_only: true },
            ],
            protected_paths: Vec::new(), memory_bytes: 4 * 1024 * 1024 * 1024,
            cpus: 2.0, cap_add: Vec::new(), workdir_change: WorkdirChange::Reject,
        }
    }
}
impl Config {
    pub fn load() -> Result<Self> {
        let config = match std::env::var_os("POLARIS_SANDBOX_CONFIG") {
            Some(path) => serde_json::from_slice(&std::fs::read(path)?)?,
            None => Self::default(),
        };
        config.validate()?;
        Ok(config)
    }
    pub fn validate(&self) -> Result<()> {
        ensure!(self.memory_bytes >= 6 * 1024 * 1024 && self.memory_bytes <= i64::MAX as u64,
            "SANDBOX_INVALID_CONFIG: memoryBytes must be 6 MiB..i64::MAX");
        ensure!(self.cpus.is_finite() && self.cpus >= 0.01 && self.cpus <= 1024.0,
            "SANDBOX_INVALID_CONFIG: cpus must be 0.01..1024");
        // Only narrowly scoped additions; administrative capabilities are never configurable.
        ensure!(self.cap_add.iter().all(|c| ["CHOWN", "FOWNER", "DAC_OVERRIDE", "NET_BIND_SERVICE"].contains(&c.as_str())),
            "SANDBOX_INVALID_CONFIG: unsupported capAdd");
        ensure!(self.mounts.len() == 2, "SANDBOX_INVALID_CONFIG: exactly /workspace and /kb required");
        for (destination, read_only) in [("/workspace", false), ("/kb", true)] {
            ensure!(self.mounts.iter().filter(|m| m.destination == destination && m.read_only == read_only).count() == 1,
                "SANDBOX_INVALID_CONFIG: /workspace must be writable and /kb read-only");
        }
        ensure!(self.protected_paths.iter().all(|p| p.is_absolute()),
            "SANDBOX_INVALID_CONFIG: protectedPaths must be absolute");
        Ok(())
    }
    pub fn protected(&self, home: &Path) -> Vec<PathBuf> {
        let mut paths: Vec<_> = ["Polaris/data", "Polaris/claude-home", "Polaris/sessions", "Polaris/conversations",
            ".polaris", ".pi", ".claude", ".codex", ".ssh", ".aws", ".gnupg", ".kube"]
            .iter().map(|p| home.join(p)).collect();
        paths.extend(self.protected_paths.iter().cloned());
        paths.extend(["/var/run", "/run", "/proc", "/sys", "/dev"].iter().map(PathBuf::from));
        paths
    }
}
//! Public policy used both before docker run and before every routed tool call.
use crate::config::Config;
use anyhow::{bail, ensure, Result};
use serde_json::Value;
use std::path::{Path, PathBuf};

pub const REBUILD_HINT: &str = "请调用 sandbox_start({projectDir:目标项目路径,rebuild:true}) 迁移；旧容器将停止并改名保留，不会删除。";

pub fn path_for_docker(path: &Path) -> String {
    let text = path.to_string_lossy();
    let text = text.trim_start_matches(r"\\?\");
    // Detect drive paths too, so Windows fixtures can be verified on Unix.
    if cfg!(windows) || (text.as_bytes().get(1) == Some(&b':') && text.as_bytes()[0].is_ascii_alphabetic()) {
        text.replace('\\', "/")
    } else { text.to_owned() }
}
fn forbidden_name(name: &str) -> bool {
    let name = name.to_ascii_lowercase();
    ["data", "claude-home", "sessions", "conversations", "providers.json", "collab.db", ".polaris", ".pi",
        ".claude", ".codex", ".ssh", ".aws", ".gnupg", ".kube"].contains(&name.as_str()) || name.ends_with(".key")
}
fn normalized(path: &Path) -> Result<PathBuf> {
    // Resolve existing ancestors even for currently absent protected directories.
    if path.exists() { return Ok(std::fs::canonicalize(path)?); }
    let parent = path.parent().ok_or_else(|| anyhow::anyhow!("SANDBOX_INVALID_PATH"))?;
    let name = path.file_name().ok_or_else(|| anyhow::anyhow!("SANDBOX_INVALID_PATH"))?;
    Ok(normalized(parent)?.join(name))
}
pub fn validate_source(source: &Path, protected: &[PathBuf]) -> Result<PathBuf> {
    ensure!(source.is_absolute(), "SANDBOX_UNSAFE_MOUNT: absolute path required; {REBUILD_HINT}");
    let source = std::fs::canonicalize(source)?;
    for path in protected {
        let path = normalized(path)?;
        ensure!(!source.starts_with(&path) && !path.starts_with(&source),
            "SANDBOX_UNSAFE_MOUNT: protected host data; {REBUILD_HINT}");
    }
    ensure!(!source.components().any(|p| forbidden_name(&p.as_os_str().to_string_lossy())),
        "SANDBOX_UNSAFE_MOUNT: forbidden path; {REBUILD_HINT}");
    ensure!(source.is_dir(), "SANDBOX_UNSAFE_MOUNT: directory required");
    // Binding a parent also exposes its children. Reject sensitive files anywhere in it.
    let mut pending = vec![source.clone()];
    while let Some(directory) = pending.pop() {
        for entry in std::fs::read_dir(directory)? {
            let entry = entry?;
            ensure!(!forbidden_name(&entry.file_name().to_string_lossy()),
                "SANDBOX_UNSAFE_MOUNT: directory contains protected files; {REBUILD_HINT}");
            // Symlinks cannot expose an unmounted host target inside the container.
            if entry.file_type()?.is_dir() { pending.push(entry.path()); }
        }
    }
    Ok(source)
}
#[derive(Debug)]
pub struct ResolvedMount { pub source: PathBuf, pub destination: String, pub read_only: bool }
impl Config {
    pub fn resolve_mounts(&self, project: &Path, kb: &Path, home: &Path) -> Result<Vec<ResolvedMount>> {
        self.validate()?;
        let protected = self.protected(home);
        let project = validate_source(project, &protected)?;
        let kb = validate_source(kb, &protected)?;
        ensure!(!project.starts_with(&kb) && !kb.starts_with(&project),
            "SANDBOX_UNSAFE_MOUNT: workspace and kb must not overlap");
        self.mounts.iter().map(|m| {
            let source = match m.source.as_str() {
                "${project}" => project.clone(), "${kb}" => kb.clone(),
                path => validate_source(Path::new(path), &protected)?,
            };
            let expected = if m.destination == "/workspace" { &project } else { &kb };
            ensure!(&source == expected, "SANDBOX_UNSAFE_MOUNT: source does not match requested root");
            Ok(ResolvedMount { source, destination: m.destination.clone(), read_only: m.read_only })
        }).collect()
    }
    pub fn run_args(&self, name: &str, image: &str, project: &Path, kb: &Path, home: &Path) -> Result<Vec<String>> {
        let mounts = self.resolve_mounts(project, kb, home)?;
        let mut args = vec!["run".into(), "-d".into(), "--name".into(), name.into(),
            format!("--memory={}", self.memory_bytes), format!("--cpus={}", self.cpus),
            "--cap-drop=ALL".into(), "--security-opt=no-new-privileges".into()];
        for capability in &self.cap_add { args.push(format!("--cap-add={capability}")); }
        for mount in mounts {
            let source = path_for_docker(&mount.source);
            ensure!(!source.contains([',', '\n', '\r']), "SANDBOX_INVALID_PATH: mount delimiter");
            args.push("--mount".into());
            args.push(format!("type=bind,src={source},dst={}{}", mount.destination,
                if mount.read_only { ",readonly" } else { "" }));
        }
        args.extend([image.into(), "sleep".into(), "infinity".into()]);
        Ok(args)
    }
    pub fn validate_container(&self, info: &Value, project: &Path, kb: &Path, home: &Path) -> Result<PathBuf> {
        let expected = self.resolve_mounts(project, kb, home)?;
        let mounts = info["Mounts"].as_array().ok_or_else(|| anyhow::anyhow!("SANDBOX_INVALID_MOUNTS"))?;
        // Check all sources first: legacy broad mounts always receive the migration diagnostic.
        for mount in mounts {
            ensure!(mount["Type"] == "bind", "SANDBOX_UNSAFE_MOUNT: unverified volume; {REBUILD_HINT}");
            let source = mount["Source"].as_str().ok_or_else(|| anyhow::anyhow!("SANDBOX_INVALID_MOUNTS"))?;
            validate_source(Path::new(source), &self.protected(home))?;
        }
        ensure!(mounts.len() == expected.len(), "SANDBOX_UNSAFE_MOUNT: unexpected mounts; {REBUILD_HINT}");
        let mut workdir_changed = false;
        for required in expected {
            let matching: Vec<_> = mounts.iter().filter(|m| m["Destination"] == required.destination).collect();
            ensure!(matching.len() == 1, "SANDBOX_UNSAFE_MOUNT: incorrect destination; {REBUILD_HINT}");
            let mount = matching[0];
            ensure!(mount["RW"].as_bool() == Some(!required.read_only),
                "SANDBOX_UNSAFE_MOUNT: incorrect access mode; {REBUILD_HINT}");
            let source = mount["Source"].as_str().ok_or_else(|| anyhow::anyhow!("SANDBOX_INVALID_MOUNTS"))?;
            if std::fs::canonicalize(source)? != required.source {
                if required.destination == "/workspace" { workdir_changed = true; }
                else { bail!("SANDBOX_UNSAFE_MOUNT: incorrect KB source; {REBUILD_HINT}"); }
            }
        }
        self.validate_security(info)?;
        ensure!(!workdir_changed, "SANDBOX_PATH_UNMOUNTED: work directory changed; {REBUILD_HINT}");
        Ok(std::fs::canonicalize(project)?)
    }
    pub fn validate_security(&self, info: &Value) -> Result<()> {
        let host = &info["HostConfig"];
        let memory = host["Memory"].as_u64().filter(|n| *n > 0 && *n <= self.memory_bytes).is_some();
        let cpu = host["NanoCpus"].as_u64().filter(|n| *n > 0 && *n <= (self.cpus * 1e9) as u64).is_some();
        let drop_all = host["CapDrop"].as_array().is_some_and(|a| a.iter().any(|v| v == "ALL"));
        let additions = host["CapAdd"].is_null() || host["CapAdd"].as_array().is_some_and(|a|
            a.iter().all(|v| v.as_str().is_some_and(|s| self.cap_add.iter().any(|c| c == s))));
        let no_new_privileges = host["SecurityOpt"].as_array().is_some_and(|a|
            a.iter().any(|v| v == "no-new-privileges" || v == "no-new-privileges:true"));
        ensure!(host["Privileged"] == false && host["PidMode"] != "host"
            && host["IpcMode"] != "host" && host["NetworkMode"] != "host"
            && host["Devices"].as_array().is_none_or(|a| a.is_empty())
            && memory && cpu && drop_all && additions && no_new_privileges,
            "SANDBOX_UNSAFE_CONTAINER: security baseline mismatch; {REBUILD_HINT}");
        Ok(())
    }
}
//! Rebuild preserves the old container by renaming it; never deletes user containers.
use crate::{config::{Config, WorkdirChange}, policy::REBUILD_HINT};
use anyhow::{ensure, Result};
use serde_json::Value;
use std::{path::Path, process::Command, sync::Mutex, time::{SystemTime, UNIX_EPOCH}};
static LIFECYCLE: Mutex<()> = Mutex::new(());

pub fn docker(args: &[String]) -> Result<String> {
    let out = Command::new("docker").args(args).output()?;
    ensure!(out.status.success(), "SANDBOX_DOCKER_FAILED: {}", String::from_utf8_lossy(&out.stderr));
    Ok(String::from_utf8_lossy(&out.stdout).trim().to_owned())
}
pub fn inspect(name: &str) -> Result<Option<Value>> {
    inspect_with(name, &mut docker)
}
fn inspect_with(name: &str, run: &mut impl FnMut(&[String]) -> Result<String>) -> Result<Option<Value>> {
    // A failed inspect is not proof of absence (daemon/permissions may be broken).
    let names = run(&["ps".into(), "-a".into(), "--format".into(), "{{.Names}}".into()])?;
    if !names.lines().any(|n| n == name) { return Ok(None); }
    let values: Vec<Value> = serde_json::from_str(&run(&["inspect".into(), name.into()])?)?;
    Ok(Some(values.into_iter().next().ok_or_else(|| anyhow::anyhow!("SANDBOX_INVALID_CONTAINER"))?))
}
#[derive(Debug, PartialEq)]
pub enum Action { Create, Reuse, PreserveAndRebuild }
pub fn decide(validation: Option<Result<std::path::PathBuf>>, config: &Config, rebuild: bool) -> Result<Action> {
    match validation {
        None => Ok(Action::Create),
        Some(Ok(_)) => Ok(Action::Reuse),
        Some(Err(error)) if rebuild || (config.workdir_change == WorkdirChange::Rebuild
            && error.to_string().starts_with("SANDBOX_PATH_UNMOUNTED:")) => Ok(Action::PreserveAndRebuild),
        Some(Err(error)) => Err(error),
    }
}
pub fn start(config: &Config, name: &str, image: &str, project: &Path, kb: &Path, home: &Path, rebuild: bool) -> Result<String> {
    let _lock = LIFECYCLE.lock().map_err(|_| anyhow::anyhow!("SANDBOX_LOCK_FAILED"))?;
    start_with(config, name, image, project, kb, home, rebuild, &mut docker)
}
fn start_with(config: &Config, name: &str, image: &str, project: &Path, kb: &Path, home: &Path,
    rebuild: bool, run: &mut impl FnMut(&[String]) -> Result<String>) -> Result<String> {
    let args = config.run_args(name, image, project, kb, home)?;
    let existing = inspect_with(name, run)?;
    let action = decide(existing.as_ref().map(|i| config.validate_container(i, project, kb, home)), config, rebuild)?;
    if action == Action::Reuse {
        run(&["start".into(), name.into()])?;
        return Ok(format!("[start ok] 已复用项目容器 {name}"));
    }
    let mut backup = None;
    if action == Action::PreserveAndRebuild {
        let stamp = SystemTime::now().duration_since(UNIX_EPOCH)?.as_nanos();
        let saved = format!("{name}-previous-{stamp}");
        run(&["stop".into(), "-t".into(), "5".into(), name.into()])?;
        run(&["rename".into(), name.into(), saved.clone()])?;
        backup = Some(saved);
    }
    match run(&args) {
        Ok(id) => Ok(format!("[run ok] {name} ({id}); 旧容器保留为 {}", backup.as_deref().unwrap_or("无"))),
        Err(error) => Err(anyhow::anyhow!("{error}; 旧容器保留为 {}; {REBUILD_HINT}", backup.as_deref().unwrap_or("无"))),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn migration_retains_old_container_and_never_deletes_it() -> Result<()> {
        let root = std::env::temp_dir().join(format!("p3b-lifecycle-{}", SystemTime::now().duration_since(UNIX_EPOCH)?.as_nanos()));
        let home = root.join("home");
        let project = root.join("project");
        let kb = root.join("kb");
        for path in [&home, &project, &kb, &home.join("Polaris")] { std::fs::create_dir_all(path)?; }
        let mut calls = Vec::<Vec<String>>::new();
        let old = serde_json::json!([{"Mounts":[
            {"Type":"bind","Source":home.join("Polaris"),"Destination":"/workspace","RW":true}]}]);
        let mut fake = |args: &[String]| -> Result<String> {
            calls.push(args.to_vec());
            Ok(match args[0].as_str() { "ps" => "managed".into(), "inspect" => old.to_string(), _ => "ok".into() })
        };
        let c = Config::default();
        assert!(start_with(&c, "managed", "image", &project, &kb, &home, false, &mut fake).is_err());
        assert!(calls.iter().all(|a| ["ps", "inspect"].contains(&a[0].as_str())));
        calls.clear();
        let mut fake = |args: &[String]| -> Result<String> {
            calls.push(args.to_vec());
            Ok(match args[0].as_str() { "ps" => "managed".into(), "inspect" => old.to_string(), _ => "ok".into() })
        };
        let message = start_with(&c, "managed", "image", &project, &kb, &home, true, &mut fake)?;
        assert!(message.contains("managed-previous-"));
        assert_eq!(calls.iter().map(|a| a[0].as_str()).collect::<Vec<_>>(), ["ps", "inspect", "stop", "rename", "run"]);
        assert!(!calls.iter().any(|a| a[0] == "rm"));
        std::fs::remove_dir_all(root)?;
        Ok(())
    }
}
//! # 板块 ⑤ 安全沙箱层 (polaris-sandbox)
//!
//! 轻量 Docker 镜像 + docker CLI 包装。设计依据 PRD-v6 §11。
//!
//! ## 板块边界 (架构重构 Phase 1)
//! 本板块已抽离为独立 crate。它**不再** `use crate::kb` —— 挂载 KB 时所需的
//! 根路径改由 host 通过 [`polaris_core::KbLocator`] 注入 (依赖反转)，故本 crate
//! 只依赖 `polaris-core` 契约，可独立 `cargo test -p polaris-sandbox`。
//!
//! ## 为什么命令放在 `commands` 子模块
//! `#[tauri::command]` 会为每个命令生成一个 `__cmd__*` 隐藏宏并 `pub(crate) use`
//! 它；当命令直接定义在 **crate 根** (lib.rs 顶层) 时，该再导入会与宏定义本身
//! 撞名 (E0255)。放进子模块即可规避，与命令在普通 `mod` 里的行为一致。
//! host 端用 `polaris_sandbox::commands::<cmd>` 注册命令 (宏需按定义模块路径解析)。

pub mod commands;
pub mod config;
pub mod policy;
pub mod lifecycle;
#[cfg(test)]
mod policy_tests;
/// CubeSandbox (E2B 兼容) 后端 —— 「替换 Docker」的可选后端 (additive)。
pub mod e2b;

// 把「可直接调用的函数」与常量再导出到 crate 根：
// 供板块① `chat` 以 `polaris_sandbox::sandbox_status()` / `::CONTAINER_NAME` 调用，
// 以及 host 在 setup 阶段调 `polaris_sandbox::init()`。
pub use commands::{init, sandbox_status, CONTAINER_NAME, IMAGE_NAME};
pub use e2b::{load_config as cube_config, CubeConfig};

//! Tool-only execution in an already managed container. Never spawns a host shell.
use super::{host_tools::{SandboxExecutor, SandboxOutput}, sandbox_process};
use std::time::{Duration, Instant};
use serde_json::Value;
use std::{path::{Path, PathBuf}, process::Command};

pub struct DockerTools {
    pub container: String,
    pub host_root: PathBuf,
    pub guest_root: String,
}
/// Reuses a container managed by polaris-sandbox, inspecting its actual mounts.
/// Old containers mounting all of ~/Polaris are rejected because they expose keys.
pub struct ManagedSandbox {
    pub container: String,
    pub protected_paths: Vec<PathBuf>,
}
impl ManagedSandbox {
    pub fn route(&self, mounts: &Value, cwd: &Path) -> anyhow::Result<DockerTools> {
        let mounts = mounts.as_array().ok_or_else(|| anyhow::anyhow!("SANDBOX_INVALID_MOUNTS"))?;
        let cwd = std::fs::canonicalize(cwd)?;
        let mut selected: Option<(PathBuf, String)> = None;
        for mount in mounts {
            anyhow::ensure!(mount["Type"] == "bind", "SANDBOX_UNVERIFIED_VOLUME");
            let source = std::fs::canonicalize(text(mount, "Source")?)?;
            let destination = text(mount, "Destination")?;
            for protected in &self.protected_paths {
                let protected = std::fs::canonicalize(protected).unwrap_or_else(|_| protected.clone());
                anyhow::ensure!(!protected.starts_with(&source) && !source.starts_with(&protected),
                    "SANDBOX_UNSAFE_MOUNT: container exposes protected host data");
            }
            anyhow::ensure!(!source.starts_with("/var/run") && !source.starts_with("/run")
                && !source.starts_with("/proc") && !source.starts_with("/sys") && !source.starts_with("/dev"),
                "SANDBOX_UNSAFE_MOUNT: host control endpoint");
            if cwd.starts_with(&source) && mount["RW"] == true
                && selected.as_ref().is_none_or(|(previous, _)| source.components().count() > previous.components().count()) {
                selected = Some((source, destination.into()));
            }
        }
        let (host_root, guest_root) = selected.ok_or_else(|| anyhow::anyhow!("SANDBOX_PATH_UNMOUNTED"))?;
        Ok(DockerTools { container: self.container.clone(), host_root, guest_root })
    }
}
impl SandboxExecutor for ManagedSandbox {
    fn execute(&self, operation: &str, args: &Value) -> anyhow::Result<SandboxOutput> {
        let start = Instant::now();
        let budget = timeout(args)?;
        let output = sandbox_process::run(Command::new("docker").args(["inspect", &self.container]), budget, output_limit(args)?)?;
        anyhow::ensure!(output.exit_code == Some(0) && !output.timed_out, "SANDBOX_UNAVAILABLE: managed container not found or inspect timed out");
        let info: Vec<Value> = serde_json::from_str(&output.output)?;
        let info = info.first().ok_or_else(|| anyhow::anyhow!("SANDBOX_INVALID_CONTAINER"))?;
        anyhow::ensure!(info["State"]["Running"] == true, "SANDBOX_UNAVAILABLE: container is stopped");
        anyhow::ensure!(info["HostConfig"]["Privileged"] != true
            && info["HostConfig"]["PidMode"] != "host"
            && info["HostConfig"]["NetworkMode"] != "host", "SANDBOX_UNSAFE_CONTAINER");
        let mut remaining = args.clone();
        let left = budget.saturating_sub(start.elapsed()).as_millis();
        anyhow::ensure!(left > 0, "SANDBOX_UNAVAILABLE: probe budget exhausted");
        remaining["timeoutMs"] = serde_json::json!(left);
        self.route(&info["Mounts"], Path::new(text(args, "cwd")?))?.execute(operation, &remaining)
    }
}
fn quote(value: &str) -> String { format!("'{}'", value.replace('\'', "'\\''")) }
fn text<'a>(args: &'a Value, key: &str) -> anyhow::Result<&'a str> {
    args.get(key).and_then(Value::as_str).ok_or_else(|| anyhow::anyhow!("SandboxMissingArgument: {key}"))
}
impl DockerTools {
    fn map_path(&self, path: &Path) -> anyhow::Result<String> {
        // Absolute host paths are only accepted under the existing managed mount.
        let root = std::fs::canonicalize(&self.host_root)?;
        let relative = path.strip_prefix(&root).map_err(|_| anyhow::anyhow!("SANDBOX_PATH_UNMOUNTED: {}", path.display()))?;
        anyhow::ensure!(!relative.components().any(|c| matches!(c, std::path::Component::ParentDir)), "SANDBOX_PATH_ESCAPE");
        Ok(format!("{}/{}", self.guest_root.trim_end_matches('/'), relative.to_string_lossy().replace('\\', "/")))
    }
    pub fn script(&self, operation: &str, args: &Value) -> anyhow::Result<(String, String)> {
        let cwd = self.map_path(Path::new(text(args, "cwd")?))?;
        let path = if ["bash", "probe"].contains(&operation) { String::new() } else {
            self.map_path(Path::new(text(args, "path")?))?
        };
        let path = quote(&path);
        let script = match operation {
            "probe" => "command -v setsid >/dev/null && command -v mktemp >/dev/null && command -v sleep >/dev/null".into(),
            "bash" => text(args, "command")?.to_owned(),
            "mkdir" => format!("mkdir -p -- {path}"),
            "access" => format!("test -r {path} && test -w {path}"),
            "read" => format!("base64 < {path}"),
            "write" => {
                use base64::Engine;
                let content = base64::engine::general_purpose::STANDARD.encode(text(args, "content")?);
                format!("printf %s {} | base64 -d > {path}", quote(&content))
            }
            _ => anyhow::bail!("SANDBOX_OPERATION_UNSUPPORTED"),
        };
        Ok((cwd, script))
    }
}
fn timeout(args: &Value) -> anyhow::Result<Duration> {
    args.get("timeoutMs").and_then(Value::as_u64).filter(|n| *n > 0 && *n <= 2_147_483_647)
        .map(Duration::from_millis).ok_or_else(|| anyhow::anyhow!("SandboxInvalidTimeout"))
}
fn output_limit(args: &Value) -> anyhow::Result<usize> {
    args.get("maxOutputBytes").and_then(Value::as_u64).filter(|n| *n > 0 && *n <= 1_048_576)
        .map(|n| n as usize).ok_or_else(|| anyhow::anyhow!("SandboxInvalidOutputLimit"))
}
const SUPERVISOR: &str = include_str!("sandbox_command.sh");
fn decode(mut output: SandboxOutput, marker: &str) -> anyhow::Result<SandboxOutput> {
    if output.timed_out || output.signal.is_some() { return Ok(output); }
    anyhow::ensure!(output.exit_code == Some(0), "SANDBOX_UNAVAILABLE: {}", output.output);
    let prefix = format!("\n{marker}:");
    let (body, trailer) = output.output.rsplit_once(&prefix)
        .ok_or_else(|| anyhow::anyhow!("SANDBOX_INVALID_RESULT"))?;
    let fields: Vec<_> = trailer.trim().split(':').collect();
    anyhow::ensure!(fields.len() == 3, "SANDBOX_INVALID_RESULT");
    let code: i32 = fields[0].parse()?;
    let signal: i32 = fields[1].parse()?;
    let timed_out: bool = fields[2].parse()?;
    output = SandboxOutput { output: body.into(), exit_code: Some(code),
        signal: if signal > 0 { Some(signal) } else { None }, timed_out };
    Ok(output)
}
impl SandboxExecutor for DockerTools {
    fn execute(&self, operation: &str, args: &Value) -> anyhow::Result<SandboxOutput> {
        let (cwd, script) = self.script(operation, args)?;
        let budget = timeout(args)?;
        let requested = args.get("timeout").and_then(Value::as_f64);
        let seconds = requested.filter(|n| n.is_finite() && *n > 0.0)
            .map_or(budget.as_secs_f64(), |n| n.min(budget.as_secs_f64()));
        let shell = text(args, "shell")?;
        anyhow::ensure!(["sh", "bash"].contains(&shell), "SandboxInvalidShell");
        let limit = output_limit(args)?;
        let mut nonce = [0u8; 16];
        getrandom::getrandom(&mut nonce).map_err(|e| anyhow::anyhow!("SandboxRandomFailed: {e}"))?;
        let marker = format!("polaris-{:x}", u128::from_le_bytes(nonce));
        // Merge command stderr inside the container; the supervisor trailer remains last.
        let script = format!("exec 2>&1\n{script}");
        let mut command = Command::new("docker");
        command.args(["exec", "-w", &cwd, &self.container, "sh", "-c", SUPERVISOR,
            "polaris-supervisor", shell, &script, &seconds.to_string(), &marker]);
        let output = sandbox_process::run(&mut command, budget, limit)?;
        decode(output, &marker)
    }
}
